import React, { useEffect, useState } from 'react';
import { progressionAPI } from '../services/api';
const MissionsPage = () => {
 const [data,setData]=useState(null); const [notice,setNotice]=useState(''); const load=async()=>{try{const r=await progressionAPI.getOverview();setData(r.data)}catch(e){console.error(e)}}; useEffect(()=>{load()},[]);
 const claim=async(key)=>{try{const r=await progressionAPI.claimQuest(key); setNotice(`+${r.data.xp_awarded} XP`); load()}catch(e){setNotice(e.response?.data?.detail||'Impossible de récupérer la quête.')}};
 if(!data)return <div className="progression-loading"><div className="spinner-border"/></div>;
 return <div className="container progression-page">{notice&&<div className="inline-notice">{notice}<button onClick={()=>setNotice('')}>×</button></div>}<section className="progression-hero"><div><span className="section-kicker">WELLCASE / DAILY OPS</span><h1>Quêtes <em>quotidiennes.</em></h1><p>Joue, ouvre et upgrade. Chaque jour te rapproche du prochain niveau.</p></div><div className="xp-summary"><span>NIVEAU {data.level}</span><strong>{data.xp.toLocaleString('fr-FR')} XP</strong><div className="xp-bar"><i style={{width:`${Math.min(100,(data.xp%500)/5)}%`}}/></div><small>{Math.max(0,data.next_level_xp-data.xp)} XP avant le niveau suivant</small></div></section><div className="quest-grid">{data.quests.map(q=><article className="quest-card" key={q.key}><div className="quest-icon">✦</div><div className="quest-copy"><span className="quest-tag">QUÊTE DU JOUR</span><h3>{q.title}</h3><p>{q.description}</p><div className="quest-progress"><div><b>{q.progress}</b> / {q.goal}</div><span>+{q.xp_reward} XP</span></div><div className="quest-track"><i style={{width:`${Math.min(100,q.progress/q.goal*100)}%`}}/></div></div><button className="quest-claim" disabled={!q.completed||q.claimed} onClick={()=>claim(q.key)}>{q.claimed?'RÉCUPÉRÉ':q.completed?'RÉCUPÉRER XP':'EN COURS'}</button></article>)}</div><section className="xp-how"><div><span className="section-kicker">PROGRESSION</span><h2>Monte de niveau en jouant</h2></div><div className="xp-how-grid"><div><b>+100 XP</b><span>Chaque ouverture</span></div><div><b>+50 XP</b><span>Chaque upgrade</span></div><div><b>+25 XP</b><span>Bonus quotidien</span></div><div><b>+120–300 XP</b><span>Quêtes</span></div></div></section></div>;
}; export default MissionsPage;
